// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address sender1, address sender2) public {
        vm.assume(sender1 != address(0) && sender2 != address(0));
        vm.assume(sender1 != sender2);
        amount1 = bound(amount1, 1, type(uint256).max / 2);
        amount2 = bound(amount2, 1, type(uint256).max / 2);

        vm.deal(sender1, amount1);
        vm.deal(sender2, amount2);

        vm.startPrank(sender1);
        c.addToBalance{value: amount1}();
        vm.stopPrank();

        bool secondOk;
        vm.startPrank(sender2);
        try c.addToBalance{value: amount2}() { secondOk = true; } catch { secondOk = false; }
        vm.stopPrank();

        assertTrue(secondOk && c.getBalance(sender1) == amount1);
    }
}
